WITH base_bal AS (    SELECT CTACTB,           SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS soma_ate_atu,           SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS soma_ate_ant,           SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 2 YEAR)) THEN VLRLANC ELSE 0 END) AS soma_ate_ant2    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE      AND (          YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) OR          YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) OR          YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 2 YEAR))      )    GROUP BY CTACTB),base_valores AS (    SELECT DET.ORDEM,           SUM(IFNULL(B.soma_ate_atu, 0) * DETCTACTB.SINAL) AS valor_base_atual,           SUM(IFNULL(B.soma_ate_ant, 0) * DETCTACTB.SINAL) AS valor_base_anterior,           SUM(IFNULL(B.soma_ate_ant2, 0) * DETCTACTB.SINAL) AS valor_base_anterior2    FROM ESTR_DEMONSTRATIVOS EST    INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO    LEFT JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA    LEFT JOIN base_bal B ON B.CTACTB = DETCTACTB.PADRAO_CTACTB    WHERE EST.ID IN (11)    GROUP BY DET.ORDEM)SELECT BV.ORDEM,       BV.valor_base_atual / 1000 AS ANO_ATUAL,       BV.valor_base_anterior / 1000 AS ANO_ANT,       BV.valor_base_anterior2 / 1000 AS ANO_BASEFROM base_valores BVORDER BY BV.ORDEM